(()=>{'use strict';
const $=id=>document.getElementById(id),B=BrowseCore,C=PlannerCore,all=LA_DATA.events,by=new Map(all.map(e=>[e.id,e]));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),url=s=>/^https?:\/\//i.test(s||'')?esc(s):'#';
const date=d=>new Date(d+'T12:00:00-07:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:'America/Los_Angeles'}),time=s=>s?new Date(s).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Los_Angeles'}):'End not published';
let selected=new Set([B.days[0]]),saved=new Set(),origin=null,zipName='',zipRequest=0,limit=30,opened=null,timer;
try{const a=JSON.parse(localStorage.getItem('fieldtrip-la-2026')||'[]');if(Array.isArray(a))saved=new Set(a.filter(id=>by.has(id)));}catch{}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,3500);}
function persist(){try{localStorage.setItem('fieldtrip-la-2026',JSON.stringify([...saved]));}catch{toast('Browser storage unavailable. Export your week before leaving.');}}
function options(){return {days:[...selected],query:$('query').value,municipality:$('municipality').value,neighborhood:$('neighborhood').value,topic:$('topic').value,format:$('format').value,sort:$('sort').value,hideClosed:$('hide-closed').checked,saved:$('saved-only').checked?saved:null,origin,radius:Number($('radius').value)};}
function opts(values){return [...new Set(values)].sort().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');}
$('municipality').insertAdjacentHTML('beforeend',B.placeGroups(all).map(g=>`<optgroup label="${esc(g.label)}">${g.options.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</optgroup>`).join(''));
$('neighborhood').insertAdjacentHTML('beforeend',opts(all.flatMap(B.neighborhoods)));$('topic').insertAdjacentHTML('beforeend',opts(all.flatMap(e=>e.themes)));$('format').insertAdjacentHTML('beforeend',opts(all.flatMap(e=>e.formats)));
$('days').innerHTML=B.days.map((d,i)=>`<label class="day"><span class="name">${['MON','TUE','WED','THU','FRI','SAT','SUN'][i]}</span><input type="radio" name="browse-day" data-day="${d}" aria-label="${date(d)}" ${i===0?'checked':''}><b>${12+i}</b><small data-count="${d}"></small></label>`).join('');
function card(e){const distance=origin?B.distance(e,origin):null;return `<article class="event-card"><span class="when">${esc(date(e.date))} · ${esc(time(e.startsAt))}${e.featured?' · FEATURED':''}</span><h3><button data-open="${e.id}">${esc(e.name)}</button></h3><div class="where">${esc(B.label(e))}${B.isLA(e)&&B.neighborhoods(e).length?' / '+esc(B.neighborhoods(e).join(', ')):''}${distance!==null?' · ≈ '+distance.toFixed(1)+' miles from ZIP':''}<br>${esc(e.hosts.join(' / '))}</div><p class="event-description">${esc(e.description||'Open the event for host details and registration.')}</p><div class="tags">${[...e.formats.slice(0,1),...e.themes.slice(0,2)].map(t=>`<span>${esc(t)}</span>`).join('')}${e.registration==='closed'?'<span>Registration closed</span>':e.access==='APPLY'?'<span>Application required</span>':''}${!e.endsAt?'<span>End not published</span>':''}</div><div class="card-actions"><button data-open="${e.id}">View event ↗</button><button class="save" data-save="${e.id}" aria-pressed="${saved.has(e.id)}" aria-label="${saved.has(e.id)?'Remove':'Save'} ${esc(e.name)}">${saved.has(e.id)?'✓ Saved':'+ Save'}</button></div></article>`;}
function render(){const o=options(),rows=B.filter(all,o),counts=B.dayCounts(all,o);$('result-count').textContent=`${rows.length} ${rows.length===1?'event':'events'} · ${date([...selected][0])}`;$('results').innerHTML=rows.length?rows.slice(0,limit).map(card).join(''):`<div class="empty"><b>${selected.size?'No events match yet.':'Choose a day to get started.'}</b>${selected.size?'Try another municipality, a wider radius or fewer filters.':'Choose a date above.'}</div>`;$('load-more').hidden=rows.length<=limit;$('saved-count').textContent=saved.size;B.days.forEach((d,i)=>{document.querySelector(`[data-count="${d}"]`).textContent=counts[i]+' events';document.querySelector(`[data-day="${d}"]`).checked=selected.has(d);});$('neighborhood-label').hidden=o.municipality!=='Los Angeles';document.querySelectorAll('.quick button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic!==undefined?o.topic===b.dataset.topic&&!o.format:o.format===b.dataset.format&&!o.topic)));paintPlan();}
function open(id){const e=by.get(id);if(!e)return;opened=id;const precision=e.geocode?'Approximate published address':e.neighborhoodGeocode?'Approximate neighborhood center':e.coords?'Approximate municipality center':'Location not mapped';$('event-content').innerHTML=`<p class="eyebrow">${esc(date(e.date))} / ${esc(time(e.startsAt))} PT</p><h2>${esc(e.name)}</h2><p class="detail-meta">${esc(e.hosts.join(' / '))}<br>${esc(B.label(e))} · ${esc(e.areas.join(' / '))}<br>${esc(time(e.startsAt))} — ${esc(time(e.endsAt))}${C.multi(e)?' · through '+esc(date(e.endDate)):''}<br>${e.registration==='closed'?'Registration closed':e.access==='APPLY'?'Application required — admission not guaranteed':'Check the host for admission and availability'}</p><div class="tags">${[...e.themes,...e.formats].map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="detail-actions"><button class="save" data-save="${e.id}" aria-pressed="${saved.has(id)}">${saved.has(id)?'✓ Saved to my week':'+ Save to my week'}</button><a href="${url(e.partiful||e.official)}" target="_blank" rel="noopener">Check host / RSVP ↗</a><a href="cartographer/#event=${e.id}">Locate in Cartographer ↗</a></div><p class="fine">${precision}. ${esc(e.publicAddress?.join(', ')||e.locationBasis)}<br>Schedule refreshed October 10 Pacific. Description: ${esc(e.descriptionDate||'October 7')}. Check the host for updates.</p><div class="description">${esc(e.description||'See the official source for event details.')}</div><a href="${url(e.official)}" target="_blank" rel="noopener">Official source ↗</a>`;if(!$('event-modal').open)$('event-modal').showModal();}
function paintPlan(){const events=[...saved].map(id=>by.get(id)).sort((a,b)=>C.start(a)-C.start(b)),warnings=C.warnings(events);$('plan-list').innerHTML=events.length?events.map(e=>`<article class="plan-row"><button class="remove" data-save="${e.id}" aria-label="Remove ${esc(e.name)}">Remove</button><small>${esc(date(e.date))} · ${esc(time(e.startsAt))} — ${esc(time(e.endsAt))}</small><button data-open="${e.id}">${esc(e.name)}</button><small>${esc(B.label(e))}</small>${warnings.get(e.id).map(w=>`<p class="conflict">${esc(w)}</p>`).join('')}${!e.endsAt?'<p class="conflict">End time unknown — confirm before planning another event afterward.</p>':''}${C.multi(e)?'<p class="conflict">Multi-day listing — check individual sessions with the host.</p>':''}<a class="fine" href="${url(e.partiful||e.official)}" target="_blank" rel="noopener">Check host ↗</a></article>`).join(''):'<p>Save an event to start your week.</p>';for(const id of ['export-calendar','share-plan','print-plan'])$(id).disabled=!events.length;}
function add(ids){for(const id of ids)if(by.has(id))saved.add(id);persist();render();toast('Added to your week. RSVP with each host.');}
function reset(){origin=null;zipName='';zipRequest++;for(const id of ['query','municipality','neighborhood','topic','format','zip'])$(id).value='';$('sort').value='time';$('hide-closed').checked=$('saved-only').checked=false;$('zip-status').textContent='Approximate distance.';limit=30;render();}
$('days').onchange=e=>{const d=e.target.dataset.day;if(!d)return;selected=new Set([d]);limit=30;render();};$('reset').onclick=reset;
for(const id of ['query','municipality','neighborhood','topic','format','sort','hide-closed','saved-only','radius'])$(id).addEventListener(id==='query'?'input':'change',()=>{if(id==='municipality')$('neighborhood').value='';limit=30;render();});
$('load-more').onclick=()=>{limit+=30;render();};document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open)open(b.dataset.open);if(b.dataset.save){const id=b.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);persist();render();if(opened===id&&$('event-modal').open)open(id);}if(b.dataset.topic!==undefined||b.dataset.format!==undefined){$('topic').value=b.dataset.topic||'';$('format').value=b.dataset.format||'';limit=30;render();}});
$('zip-form').onsubmit=async e=>{e.preventDefault();const zip=$('zip').value.trim();if(!/^\d{5}$/.test(zip)){$('zip-status').textContent='Enter a five-digit US ZIP code.';return;}const request=++zipRequest;origin=null;render();$('zip-status').textContent='Looking up ZIP '+zip+'…';try{const r=await fetch('https://api.zippopotam.us/us/'+zip,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('ZIP not found');const data=await r.json(),p=data.places?.[0],coords=[Number(p?.longitude),Number(p?.latitude)];if(!p||!coords.every(Number.isFinite))throw Error('No location');if(request!==zipRequest)return;origin=coords;zipName=zip+' / '+p['place name'];$('zip-status').textContent=`Near ${zipName}. Approximate straight-line distance; municipality-center locations may be imprecise. Events with no coordinates are excluded.`;limit=30;render();}catch{if(request===zipRequest){origin=null;$('zip-status').textContent='Could not find that ZIP. Check the code or try again. No ZIP filter applied.';render();}}};
$('zip-clear').onclick=()=>{zipRequest++;origin=null;zipName='';$('zip').value='';$('zip-status').textContent='ZIP filter cleared.';render();};$('my-week').onclick=()=>{$('plan-modal').showModal();};for(const [close,modal] of [['event-close','event-modal'],['plan-close','plan-modal'],['notes-close','notes-modal']])$(close).onclick=()=>$(modal).close();$('event-modal').addEventListener('close',()=>opened=null);$('data-notes').onclick=()=>$('notes-modal').showModal();$('freshness').textContent=`${all.length} official events. Schedule refreshed October 10, 2026 Pacific. ${PLANNER_META.unknownEnds} events have no published end time.`;
$('export-calendar').onclick=()=>{const events=[...saved].map(id=>by.get(id)).sort((a,b)=>C.start(a)-C.start(b)),blob=new Blob([C.ics(events)],{type:'text/calendar;charset=utf-8'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='fieldtrip-la-tech-week.ics';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);};$('print-plan').onclick=()=>window.print();
window.Fieldtrip={open,add,getState:()=>({saved:[...saved],days:[...selected],day:selected.size===1?[...selected][0]:'',matching:B.filter(all,options()).map(e=>e.id)}),routePool:o=>B.filter(all,{...options(),days:undefined,municipality:o.municipality||'',neighborhood:o.municipality===options().municipality?options().neighborhood:'',saved:null,sort:'time'})};render();
})();
